definitions.PokemonBattleAgent:
class PokemonBattleAgent:
    """Use an AdvancedSearchEngine to choose Pokémon actions."""

    def __init__(self, engine: Any) -> None:
        self.engine = engine

    def choose_move(
        self,
        state: Any,
        depth: int = 6,
    ) -> AgentDecision:
        """Search the current state and return the selected move."""

        result = self.engine.search_depth(
            state=state,
            depth=depth,
            clear_table=True,
        )

        if result.best_move is None:
            raise RuntimeError(
                "The search engine did not return a legal move."
            )

        return AgentDecision(
            move=result.best_move,
            score=result.score,
            search_depth=result.completed_depth,
            nodes=result.stats.nodes,
            principal_variation=result.principal_variation,
        )

definitions.get_legal_moves:
def get_legal_moves(
    pokemon_state: PokemonState,
) -> List[Move]:
    """
    Return every attack currently usable by the selected Pokémon.

    Saved attack dictionaries use:

    - Move Name
    - damage_numeric
    - energy_cost
    - Effect Explanation
    """

    legal_moves: List[Move] = []

    attacks = pokemon_state.card.get("attacks", [])

    if not isinstance(attacks, list):
        return legal_moves

    for attack in attacks:
        if not isinstance(attack, dict):
            continue

        move_name = attack.get(
            "Move Name",
            "Unknown Move",
        )

        try:
            damage = float(
                attack.get("damage_numeric", 0) or 0
            )
        except (TypeError, ValueError):
            damage = 0.0

        try:
            required_energy = int(
                attack.get("energy_cost", 0) or 0
            )
        except (TypeError, ValueError):
            required_energy = 0

        usable = (
            pokemon_state.attached_energy
            >= required_energy
        )

        if usable:
            legal_moves.append(
                {
                    "name": str(move_name),
                    "damage": damage,
                    "energy_cost": required_energy,
                    "effect": attack.get(
                        "Effect Explanation"
                    ),
                }
            )

    return legal_moves

definitions.get_current_side_pokemon:
def get_current_side_pokemon(
    battle_state: BattleState,
) -> PokemonState:
    """Return the Active Pokémon belonging to the current side."""

    if battle_state.current_player == "Player":
        return battle_state.player.active

    if battle_state.current_player == "Opponent":
        return battle_state.opponent.active

    raise ValueError(
        "current_player must be 'Player' or 'Opponent'."
    )

definitions.get_current_legal_moves:
def get_current_legal_moves(
    battle_state: BattleState,
) -> List[Move]:
    """
    Return legal moves for whichever side currently has the turn.

    When no attack is available, return a Pass action so the search
    tree can continue to the next turn.
    """

    active_pokemon = get_current_side_pokemon(
        battle_state
    )

    legal_moves = get_legal_moves(
        active_pokemon
    )

    if not legal_moves:
        return [
            {
                "name": "Pass",
                "damage": 0.0,
                "energy_cost": 0,
                "effect": "No legal attack was available.",
            }
        ]

    return legal_moves

definitions.move_label:
def move_label(
    move: Any,
) -> str:
    if isinstance(move, dict):
        return str(
            move.get("name")
            or move.get("Move Name")
            or move
        )

    for attribute in [
        "name",
        "move_name",
        "action",
        "attack_name",
    ]:
        value = getattr(
            move,
            attribute,
            None,
        )

        if value:
            return str(value)

    return str(move)

definitions.numeric_move_value:
def numeric_move_value(
    move: Any,
    *candidate_names: str,
    default: float = 0.0,
) -> float:
    if isinstance(move, dict):
        for name in candidate_names:
            value = move.get(name)

            if value is not None:
                try:
                    return float(value)
                except (TypeError, ValueError):
                    continue

        return default

    for name in candidate_names:
        value = getattr(
            move,
            name,
            None,
        )

        if value is not None:
            try:
                return float(value)
            except (TypeError, ValueError):
                continue

    return default

definitions.determine_battle_winner:
def determine_battle_winner(
    state: BattleState,
) -> Optional[str]:
    """Return the winner when the battle reaches a terminal state."""

    player_hp = state.player.active.current_hp
    opponent_hp = state.opponent.active.current_hp

    if player_hp <= 0 and opponent_hp <= 0:
        return "Draw"

    if opponent_hp <= 0:
        return "Player"

    if player_hp <= 0:
        return "Opponent"

    if state.player.prize_cards_remaining <= 0:
        return "Player"

    if state.opponent.prize_cards_remaining <= 0:
        return "Opponent"

    return None

definitions.create_battle_transcript:
def create_battle_transcript(
    simulation: BattleSimulationResult,
) -> str:
    """Create a readable text transcript for a simulation."""

    lines = [
        "=" * 70,
        "POKÉMON AI BATTLE TRANSCRIPT",
        "=" * 70,
    ]

    for turn in simulation.turns:
        lines.append(
            f"Turn {turn.turn_number}: "
            f"{turn.acting_side} — "
            f"{turn.pokemon_name} used "
            f"{turn.move_name}"
        )

        lines.append(
            f"  Damage: {turn.damage:.1f}"
        )

        lines.append(
            f"  Search score: {turn.score:.2f}"
        )

        lines.append(
            f"  Search depth: {turn.search_depth}"
        )

        lines.append(
            f"  Nodes searched: {turn.nodes}"
        )

        lines.append(
            "  HP after move — "
            f"Player: {turn.player_hp_after:.1f}, "
            f"Opponent: {turn.opponent_hp_after:.1f}"
        )

        lines.append(
            f"  Next side: {turn.next_side}"
        )

        lines.append("-" * 70)

    lines.append(f"Winner: {simulation.winner}")
    lines.append(f"Stop reason: {simulation.stop_reason}")

    return "\n".join(lines)

definitions.BattleState:
class BattleState:
    """Complete position used by minimax and advanced search."""

    player: PlayerState
    opponent: PlayerState
    turn_number: int
    current_player: str

    def __post_init__(self) -> None:
        if self.current_player not in {"Player", "Opponent"}:
            raise ValueError(
                "current_player must be 'Player' or 'Opponent'."
            )
